ALTER TABLE users ADD COLUMN IF NOT EXISTS role TEXT NOT NULL DEFAULT 'teacher' CHECK(role IN ('teacher','staff'));
CREATE TABLE pilot_checks(id UUID PRIMARY KEY,owner_id UUID NOT NULL REFERENCES users(id),title TEXT NOT NULL,phase TEXT NOT NULL DEFAULT 'editing' CHECK(phase IN ('editing','review','finalized')),revision BIGINT NOT NULL DEFAULT 0,data_revision BIGINT NOT NULL DEFAULT 0,next_notebook_number INTEGER NOT NULL DEFAULT 1,selected_summary_job_id UUID,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),deleted BOOLEAN NOT NULL DEFAULT false,graph JSONB NOT NULL DEFAULT '{"notebooks":[]}');
CREATE TABLE pilot_notebooks(id UUID PRIMARY KEY,check_id UUID NOT NULL REFERENCES pilot_checks(id),number INTEGER NOT NULL,deleted BOOLEAN NOT NULL DEFAULT false,UNIQUE(check_id,number));
CREATE TABLE pilot_bundles(id UUID PRIMARY KEY,check_id UUID NOT NULL REFERENCES pilot_checks(id),notebook_id UUID NOT NULL REFERENCES pilot_notebooks(id),deleted BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE pilot_input_versions(id UUID PRIMARY KEY,bundle_id UUID NOT NULL REFERENCES pilot_bundles(id),state TEXT NOT NULL CHECK(state IN ('draft','sealed')),payload JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),discarded BOOLEAN NOT NULL DEFAULT false);
CREATE UNIQUE INDEX pilot_one_draft ON pilot_input_versions(bundle_id) WHERE state='draft' AND NOT discarded;
CREATE TABLE pilot_photo_assets(id UUID PRIMARY KEY,check_id UUID NOT NULL REFERENCES pilot_checks(id),bundle_id UUID NOT NULL REFERENCES pilot_bundles(id),original_path TEXT NOT NULL,normalized_path TEXT NOT NULL,media_type TEXT NOT NULL,sha256 TEXT NOT NULL,byte_count BIGINT NOT NULL,width INTEGER NOT NULL,height INTEGER NOT NULL);
CREATE TABLE pilot_version_photos(version_id UUID NOT NULL REFERENCES pilot_input_versions(id),photo_id UUID NOT NULL REFERENCES pilot_photo_assets(id),position INTEGER NOT NULL CHECK(position>0),PRIMARY KEY(version_id,photo_id),UNIQUE(version_id,position));
CREATE TABLE pilot_snapshots(id UUID PRIMARY KEY,check_id UUID NOT NULL REFERENCES pilot_checks(id),data_revision BIGINT NOT NULL,payload JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE pilot_jobs(id UUID PRIMARY KEY,check_id UUID NOT NULL REFERENCES pilot_checks(id),bundle_id UUID REFERENCES pilot_bundles(id),kind TEXT NOT NULL CHECK(kind IN ('page_check','class_analytics')),input_version_id UUID REFERENCES pilot_input_versions(id),snapshot_id UUID REFERENCES pilot_snapshots(id),state TEXT NOT NULL DEFAULT 'queued' CHECK(state IN ('queued','running','retry_wait','blocked','unknown','succeeded','failed','cancelled','superseded')),reason TEXT,epoch BIGINT NOT NULL DEFAULT 0,worker_id UUID,lease_until TIMESTAMPTZ,auto_retry_count INTEGER NOT NULL DEFAULT 0 CHECK(auto_retry_count BETWEEN 0 AND 1),next_run_at TIMESTAMPTZ NOT NULL DEFAULT now(),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK((kind='page_check' AND input_version_id IS NOT NULL AND snapshot_id IS NULL AND bundle_id IS NOT NULL) OR (kind='class_analytics' AND input_version_id IS NULL AND snapshot_id IS NOT NULL AND bundle_id IS NULL)));
CREATE INDEX pilot_queue ON pilot_jobs(next_run_at,created_at) WHERE state IN ('queued','retry_wait','blocked');
CREATE TABLE pilot_attempts(id UUID PRIMARY KEY,job_id UUID NOT NULL REFERENCES pilot_jobs(id),ordinal INTEGER NOT NULL,epoch BIGINT NOT NULL,state TEXT NOT NULL CHECK(state IN ('started','settled','unknown','rejected')),dispatched BOOLEAN NOT NULL DEFAULT false,provider_request_id TEXT,actual_cost_rub NUMERIC,raw_response TEXT,evidence JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(job_id,ordinal));
CREATE TABLE pilot_workers(id UUID PRIMARY KEY,identity TEXT NOT NULL,heartbeat_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE pilot_bundle_reports(id UUID PRIMARY KEY,job_id UUID NOT NULL UNIQUE REFERENCES pilot_jobs(id),input_version_id UUID NOT NULL REFERENCES pilot_input_versions(id),report JSONB NOT NULL);
CREATE TABLE pilot_task_analyses(id UUID PRIMARY KEY,task_id UUID NOT NULL UNIQUE,job_id UUID NOT NULL REFERENCES pilot_jobs(id),report_id UUID NOT NULL REFERENCES pilot_bundle_reports(id),analysis JSONB NOT NULL,deleted BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE pilot_reviews(analysis_id UUID PRIMARY KEY REFERENCES pilot_task_analyses(id),state TEXT NOT NULL CHECK(state IN ('confirmed','system_error')),comment TEXT NOT NULL);
CREATE TABLE pilot_analytics_results(job_id UUID PRIMARY KEY REFERENCES pilot_jobs(id),snapshot_id UUID NOT NULL REFERENCES pilot_snapshots(id),result JSONB NOT NULL);
CREATE TABLE pilot_idempotency(actor_id UUID NOT NULL REFERENCES users(id),method TEXT NOT NULL,path TEXT NOT NULL,key UUID NOT NULL,payload_hash TEXT NOT NULL,status INTEGER NOT NULL,body JSONB NOT NULL,PRIMARY KEY(actor_id,method,path,key));
CREATE TABLE pilot_outbox(id UUID PRIMARY KEY,event_name TEXT NOT NULL,check_id UUID,entity_id UUID,payload JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE pilot_events(actor_id UUID NOT NULL REFERENCES users(id),id UUID NOT NULL,role TEXT NOT NULL,payload JSONB NOT NULL,received_at TIMESTAMPTZ NOT NULL DEFAULT now(),PRIMARY KEY(actor_id,id));
CREATE TABLE pilot_audit(id UUID PRIMARY KEY,actor_id UUID,role TEXT NOT NULL,request_id UUID NOT NULL,name TEXT NOT NULL,check_id UUID,entity_id UUID,payload JSONB NOT NULL DEFAULT '{}',created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE pilot_funds(mode TEXT PRIMARY KEY CHECK(mode IN ('fixture','polza')),balance_rub NUMERIC NOT NULL DEFAULT 0,held_rub NUMERIC NOT NULL DEFAULT 0,initialized BOOLEAN NOT NULL DEFAULT false,profile_id TEXT,paused BOOLEAN NOT NULL DEFAULT false,CHECK(held_rub>=0));
INSERT INTO pilot_funds(mode) VALUES ('fixture'),('polza');
CREATE TABLE pilot_fund_reservations(attempt_id UUID PRIMARY KEY REFERENCES pilot_attempts(id),mode TEXT NOT NULL REFERENCES pilot_funds(mode),amount_rub NUMERIC NOT NULL CHECK(amount_rub>=0),active BOOLEAN NOT NULL DEFAULT true);
CREATE TABLE pilot_fund_ledger(id UUID PRIMARY KEY,mode TEXT NOT NULL REFERENCES pilot_funds(mode),request_id UUID NOT NULL UNIQUE,attempt_id UUID REFERENCES pilot_attempts(id),operation TEXT NOT NULL,amount_rub NUMERIC NOT NULL,payload_hash TEXT NOT NULL,evidence JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE UNIQUE INDEX pilot_one_settlement ON pilot_fund_ledger(attempt_id) WHERE operation='settlement';
CREATE TABLE pilot_slots(id INTEGER PRIMARY KEY CHECK(id BETWEEN 1 AND 2),attempt_id UUID UNIQUE REFERENCES pilot_attempts(id),job_id UUID REFERENCES pilot_jobs(id),epoch BIGINT);
INSERT INTO pilot_slots(id) VALUES(1),(2);
CREATE FUNCTION pilot_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable pilot material'; END $$;
CREATE TRIGGER pilot_report_immutable BEFORE UPDATE OR DELETE ON pilot_bundle_reports FOR EACH ROW EXECUTE FUNCTION pilot_immutable();
CREATE TRIGGER pilot_snapshot_immutable BEFORE UPDATE OR DELETE ON pilot_snapshots FOR EACH ROW EXECUTE FUNCTION pilot_immutable();
CREATE TRIGGER pilot_result_immutable BEFORE UPDATE OR DELETE ON pilot_analytics_results FOR EACH ROW EXECUTE FUNCTION pilot_immutable();
CREATE FUNCTION pilot_sealed_links() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE vid UUID; BEGIN vid := COALESCE(NEW.version_id,OLD.version_id); IF EXISTS(SELECT 1 FROM pilot_input_versions WHERE id=vid AND state='sealed') THEN RAISE EXCEPTION 'sealed input immutable'; END IF; RETURN COALESCE(NEW,OLD); END $$;
CREATE TRIGGER pilot_link_immutable BEFORE INSERT OR UPDATE OR DELETE ON pilot_version_photos FOR EACH ROW EXECUTE FUNCTION pilot_sealed_links();
CREATE FUNCTION pilot_sealed_version() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.state='sealed' THEN RAISE EXCEPTION 'sealed input immutable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER pilot_version_immutable BEFORE UPDATE OR DELETE ON pilot_input_versions FOR EACH ROW EXECUTE FUNCTION pilot_sealed_version();
